        // **********************************************************************************************************
        /**
         * Sends an elasticsearch request using the current settings found in the HTML page for input (filters)
         * and output (chart(s) to create).
         *
         * @param currentInputSettings       The filters to be used for the search
         * @param currentOutputSettings      The settings for the chart to be created as well as the parameters
         *                                   to be used for the aggregation part of the query
         *
         * Returned is a promise. In case of success the resolve function is called with the payload of the
         * elasticsearch response.
         *
         * @return {Promise<unknown>}
         */
        this.doSearchWithCurrentUserSettings = function (currentInputSettings, currentOutputSettings) {
            return new Promise((resolve, reject) => {
                try {
                    console.debug('Input parameters:', JSON.stringify(currentInputSettings), 'Output parameters:', JSON.stringify(currentOutputSettings));
                    const outputSettingsEnrichedWithMetadata = _getOutputDimensionsEnrichedWithMetadata(currentOutputSettings);
                    //console.debug('Output settings enriched with metadata', outputSettingsEnrichedWithMetadata);
                    // Make sure special values are taken into account, when creating search parameters
                    const ajaxCallDataParameters = m_elasticsearchModel.createSearchParametersAccordingToUserInput( currentInputSettings, profilingConfiguratorToUse.handleSpecialValues );
                    _addAggregationsForOutput(outputSettingsEnrichedWithMetadata, ajaxCallDataParameters);
                    console.debug('Will send elasticsearch request using data', JSON.stringify(ajaxCallDataParameters), ajaxCallDataParameters);

                    m_elasticsearchModel.executeSearchWithRequestData(ajaxCallDataParameters)
                        .then((elasticsearchData) => {
                            if (elasticsearchData) {
                                console.debug('Got data', elasticsearchData, 'will draw data using', outputSettingsEnrichedWithMetadata);

                                const data = {
                                    aggregations: elasticsearchData.aggregations,
                                    totalCount: ElasticsearchModel.getNumberOfTotalHits(elasticsearchData.hits),
                                };
                                adjustOutputSettingsThenDrawData(data, outputSettingsEnrichedWithMetadata);
                                m_htmlInputModel.switchFeedbackToOkay(m_profilingControllerOptions.feedbackSelector);
                                resolve(ajaxCallDataParameters, data);
                            }
                        })
                        .catch((err) => { reject(err)});

                    m_htmlInputModel.switchFeedbackToWorking(m_profilingControllerOptions.feedbackSelector);
                }
